mapper.select:
SELECT t1.corp_gr AS corpGr , TO_CHAR(t1.tr_ymd, 'YYYY-MM-DD') AS trYmd , t1.fund_cd AS fundCd , t1.t0_aek AS t0Aek , t1.t1_aek AS t1Aek , t1.t2_aek AS t2Aek , t1.stock_aek AS stockAek , t1.bond_aek AS bondAek , t1.rp_aek AS rpAek , t1.tot_aek AS totAek , ia.fund_nm AS fundNm , t1.tr_co_cd AS trCoCd , t1.enc_acct_no AS encAcctNo , t1.bigo AS bigo , TO_DECRYPTS (t1.enc_acct_no) AS acctNo FROM SHT0YE t1 JOIN SZM0IA ia ON ia.corp_gr = t1.corp_gr AND ia.fund_cd = t1.fund_cd WHERE t1.corp_gr = #{corpGr} AND TRUNC(t1.tr_ymd) = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
AND t1.tr_co_cd = #{trCoCd}
ORDER BY t1.fund_cd
